// Unit Test: Mocking I/O to test business logic
@Test
void processData_ShouldHandleEmptyFile() {
    InputStream mockStream = new ByteArrayInputStream(new byte[0]);
    DataProcessor processor = new DataProcessor();
    assertThrows(EmptyFileException.class, () -> processor.process(mockStream));
}

// Integration Test: Verifying actual NIO FileChannel interaction
@Test
void writeToFile_ShouldPersistToDisk() throws IOException {
    Path tempFile = Files.createTempFile("test", ".txt");
    try (FileChannel channel = FileChannel.open(tempFile, StandardOpenOption.WRITE)) {
        ByteBuffer buffer = ByteBuffer.wrap("data".getBytes());
        channel.write(buffer);
    }
    assertEquals("data", Files.readString(tempFile));
}
